            switch entry.family {
            case .quantity: type = HKObjectType.quantityType(forIdentifier: HKQuantityTypeIdentifier(rawValue: entry.identifier))
            case .category: type = HKObjectType.categoryType(forIdentifier: HKCategoryTypeIdentifier(rawValue: entry.identifier))
            case .correlation: type = HKObjectType.correlationType(forIdentifier: HKCorrelationTypeIdentifier(rawValue: entry.identifier))
            case .clinical: type = HKObjectType.clinicalType(forIdentifier: HKClinicalTypeIdentifier(rawValue: entry.identifier))
